function validate([s]) {
  if (typeof s !== 'string' || s.length < 1 || s.length > 50) return 's needs 1 to 50 characters.';
  if (!/^[01]+$/.test(s)) return 's holds only 0 and 1.';
  let balance = 0;
  for (const c of s) {
    balance += c === '1' ? 1 : -1;
    if (balance < 0) return 'No prefix of s may have more 0s than 1s.';
  }
  if (balance !== 0) return 's needs as many 1s as 0s.';
  return null;
}

