function makeLargestSpecial(s) {
  const mountains = [];
  let balance = 0;
  let start = 0;
  for (let i = 0; i < s.length; i++) {
    balance += s[i] === '1' ? 1 : -1;
    if (balance === 0) {
      const inner = makeLargestSpecial(s.slice(start + 1, i));
      mountains.push('1' + inner + '0');
      start = i + 1;
    }
  }
  mountains.sort().reverse();
  return mountains.join('');
}

