function makeLargestSpecial(s) {
  // Explore every string reachable by moves and keep the greatest.
  const special = t => {
    let b = 0;
    for (const c of t) { b += c === '1' ? 1 : -1; if (b < 0) return false; }
    return b === 0;
  };
  const seen = new Set([s]);
  const queue = [s];
  let best = s;
  for (let head = 0; head < queue.length; head++) {
    const cur = queue[head];
    if (cur > best) best = cur;
    const n = cur.length;
    for (let i = 0; i < n; i++)
      for (let j = i + 2; j < n; j += 2) {
        if (!special(cur.slice(i, j))) continue;
        for (let k = j + 2; k <= n; k += 2) {
          if (!special(cur.slice(j, k))) continue;
          const next = cur.slice(0, i) + cur.slice(j, k) + cur.slice(i, j) + cur.slice(k);
          if (!seen.has(next)) { seen.add(next); queue.push(next); }
        }
      }
  }
  return best;
}

