function generate(rand, size) {
  const pairs = size === 'large' ? 20 + Math.floor(rand() * 6) : 1 + Math.floor(rand() * 7);
  const up = 0.3 + rand() * 0.4;
  let s = '';
  let balance = 0;
  let ones = 0;
  while (s.length < 2 * pairs) {
    if (balance === 0 || (ones < pairs && rand() < up)) {
      s += '1';
      balance++;
      ones++;
    } else {
      s += '0';
      balance--;
    }
  }
  return [s];
}
